init_dist();
import { mkdirSync as mkdirSync3, writeFileSync as writeFileSync2 } from "fs";
import * as path14 from "path";
var REQUIRED_MARKERS = [
  "# STEP-X JUDGMENT",
  "## 1. THE EXECUTIVE SUMMARY",
  "## 2. THE FINDING BLOCKS",
  "## 3. THE RED-HERRINGS"
];
var WRITE_SCHEMA = exports_typebox.Object({
  content: exports_typebox.String({ description: "The COMPLETE judgment markdown document, including every required section and one ### FINDING n block per finding." })
});
function createReportWriteTool(judgmentPath) {
  return {
    name: "report_write",
    label: "report-write",
    description: `Write the COMPLETE judgment document to ${judgmentPath} (the ONLY writable path \u2014 mechanically enforced). Required sections, in order: '# STEP-X JUDGMENT', '## 1. THE EXECUTIVE SUMMARY', '## 2. THE FINDING BLOCKS' (containing one '### FINDING n' machine block per finding: ADJUDICATION / DEEPER ROOT / CONCRETE FIX / CONSEQUENCE RANK), '## 3. THE RED-HERRINGS'. Write the WHOLE document in ONE call.`,
    parameters: WRITE_SCHEMA,
    execute: async (_toolCallId, params, _signal) => {
      const p = params ?? {};
      const content = typeof p.content === "string" ? p.content : "";
      if (content.trim().length === 0) {
        return { content: [{ type: "text", text: "REPORT_WRITE_REJECTED: empty content is not a judgment" }], details: null };
      }
      const missing = REQUIRED_MARKERS.filter((m) => !content.includes(m));
      if (missing.length > 0) {
        return {
          content: [{ type: "text", text: `REPORT_WRITE_REJECTED: missing required section(s): ${missing.join(" | ")}` }],
          details: null
        };
      }
      const findingBlocks = (content.match(/^#{0,4}\s*\**FINDING\s+\d+/gim) ?? []).length;
      if (findingBlocks === 0) {
        return {
          content: [{ type: "text", text: "REPORT_WRITE_REJECTED: zero FINDING blocks \u2014 every finding needs its ### FINDING n verdict block" }],
          details: null
        };
      }
      try {
        mkdirSync3(path14.dirname(judgmentPath), { recursive: true });
        writeFileSync2(judgmentPath, content, "utf-8");
      } catch (err2) {
        return {
          content: [{ type: "text", text: `REPORT_WRITE_FAILED: ${err2 instanceof Error ? err2.message : String(err2)}` }],
          details: null
        };
      }
      return {
        content: [{ type: "text", text: `JUDGMENT WRITTEN: ${judgmentPath} (${content.split(`
`).length} lines, ${findingBlocks} finding blocks)` }],
        details: null
      };
    }
  };
}

