  if (!isPredicate(mapped3))
    throw new Error(`GRAPH_TAG_INVALID_PREDICATE: ${predicate} not in ontology`);
  predicate = mapped3;
  if (!isNodeType(kind))
    throw new Error(`GRAPH_TAG_INVALID_KIND: ${kind}`);
