// src/warheads/xstate-fsm/index.ts
var EVT_SCAN_DONE = "SCAN_COMPLETE";
var EVT_ANALYSIS_DONE = "ANALYSIS_COMPLETE";
var EVT_REPORT_DONE = "REPORT_COMPLETE";
var auditMachine = import_xstate_cjs.createMachine({
  id: "audit",
  types: { context: {}, events: {} },
  initial: "idle",
  context: {
    targetPath: "",
    currentLayer: 0,
    maxLayers: 17,
    filesFound: 0,
    findings: 0,
    error: null,
    startTime: 0
  },
  states: {
    idle: {
      on: {
        START_SCAN: {
          target: "scanning",
          actions: ({ context: context3, event }) => {
            context3.targetPath = event.targetPath;
            context3.startTime = Date.now();
            tridentLog("FSM", "xstate", `Transition: idle \u2192 scanning (${event.targetPath})`);
          }
        }
      }
    },
    scanning: {
      on: {
        SCAN_COMPLETE: {
          target: "analyzing",
          actions: ({ context: context3, event }) => {
            context3.filesFound = event.filesFound;
            tridentLog("FSM", "xstate", `Transition: scanning \u2192 analyzing (${event.filesFound} files)`);
          }
        },
        FAIL: {
          target: "failed",
          actions: ({ context: context3, event }) => {
            context3.error = event.error;
            tridentLog("FSM", "xstate", `Transition: scanning \u2192 failed (${event.error})`);
          }
        }
      }
    },
    analyzing: {
      on: {
        ANALYSIS_COMPLETE: {
          target: "reporting",
          actions: ({ context: context3, event }) => {
            context3.findings = event.findings;
            tridentLog("FSM", "xstate", `Transition: analyzing \u2192 reporting (${event.findings} findings)`);
          }
        },
        FAIL: {
          target: "failed",
          actions: ({ context: context3, event }) => {
            context3.error = event.error;
            tridentLog("FSM", "xstate", `Transition: analyzing \u2192 failed (${event.error})`);
          }
        }
      }
    },
    reporting: {
      on: {
        REPORT_COMPLETE: {
          target: "done",
          actions: ({ context: context3 }) => {
            tridentLog("FSM", "xstate", `Transition: reporting \u2192 done (findings: ${context3.findings})`);
          }
        },
        FAIL: {
          target: "failed",
          actions: ({ context: context3, event }) => {
            context3.error = event.error;
          }
        }
      }
    },
    failed: {
      on: {
        RESET: {
          target: "idle",
          actions: ({ context: context3 }) => {
            context3.error = null;
            context3.currentLayer = 0;
            tridentLog("FSM", "xstate", "Transition: failed \u2192 idle (reset)");
          }
        }
      }
    },
    done: {
      type: "final"
    },
    inconclusive: {
      type: "final"
    }
  }
});

class AuditFSM {
  service;
  actor;
  constructor() {
    this.actor = import_xstate_cjs.interpret(auditMachine);
    this.service = this.actor;
  }
  start() {
    this.actor.start();
    tridentLog("INFO", "xstate-fsm", "AuditFSM started");
    return this;
  }
  send(event) {
    const cur = this.getState();
    if ((cur === "done" || cur === "inconclusive") && event.type === "RESET") {
      this.actor.stop();
      this.actor = import_xstate_cjs.interpret(auditMachine);
      this.service = this.actor;
      this.actor.start();
      tridentLog("INFO", "xstate-fsm", `AuditFSM reset from ${cur} \u2192 idle (actor recreated, type:'final' terminal handled via lifecycle)`);
      return;
    }
    if ((cur === "done" || cur === "inconclusive") && event.type === "START_SCAN") {
      this.actor.stop();
      this.actor = import_xstate_cjs.interpret(auditMachine);
      this.service = this.actor;
      this.actor.start();
      tridentLog("INFO", "xstate-fsm", `AuditFSM auto-reset from ${cur} for new scan`);
    }
    this.actor.send(event);
  }
  getState() {
    const value = this.actor.getSnapshot().value;
    return typeof value === "string" ? value : "unknown";
  }
  getContext() {
    return this.actor.getSnapshot().context;
  }
  isRunning() {
    const state2 = this.getState();
    return state2 !== "idle" && state2 !== "failed" && state2 !== "done" && state2 !== "inconclusive";
  }
  stop() {
    this.actor.stop();
    tridentLog("INFO", "xstate-fsm", "AuditFSM stopped");
  }
  async runFullCycle(targetPath) {
    this.send({ type: "START_SCAN", targetPath });
    const fs34 = await import("fs");
    const path40 = await import("path");
    let filesFound = 0;
    let scanError = null;
    const skipDirs = new Set(["node_modules", "dist", ".git", ".trident"]);
    const walk = (dir) => {
      try {
        const entries = fs34.readdirSync(dir, { withFileTypes: true });
        for (const entry of entries) {
          if (skipDirs.has(entry.name))
            continue;
          const full = path40.join(dir, entry.name);
          if (entry.isDirectory()) {
            walk(full);
          } else if (entry.name.endsWith(".ts") && !entry.name.endsWith(".d.ts")) {
            filesFound++;
          }
        }
      } catch (e) {
        scanError = e instanceof Error ? e.message : String(e);
        tridentLog("ERROR", "xstate-fsm", `[AuditFSM] scan error: ${scanError}`);
      }
    };
    walk(targetPath);
    if (scanError !== null) {
      this.send({ type: "FAIL", error: scanError });
      return { state: this.getState(), context: this.getContext() };
    }
    this.send({ type: EVT_SCAN_DONE, filesFound });
    this.send({ type: "START_ANALYSIS", mode: "full" });
    let findings;
    try {
      const engine4 = new AuditEngine;
      const result2 = await engine4.audit(targetPath);
      findings = result2.findings.length;
    } catch (e) {
      this.send({ type: "FAIL", error: e instanceof Error ? e.message : String(e) });
      return { state: this.getState(), context: this.getContext() };
    }
    this.send({ type: EVT_ANALYSIS_DONE, findings });
    this.send({ type: "START_REPORT", format: "markdown" });
    this.send({ type: EVT_REPORT_DONE });
    tridentLog("INFO", "xstate-fsm", `Audit cycle complete for ${targetPath} (${filesFound} files found, ${findings} findings)`);
    return { state: this.getState(), context: this.getContext() };
  }
}

