    id: "CR-SHAPE-SCENARIOS",
    kind: "shape",
    triggerCondition: "scenarios is missing, not an array, or empty",
    severity: "BLOCK",
    messageTemplate: "scenarios must be a non-empty array",
    match: (p) => !Array.isArray(p.scenarios) || p.scenarios.length === 0
