function findMatchingDefense(threat, defenses) {
  return defenses.find((d) => {
    const threatKey = threat.pattern.toLowerCase();
    const threatKeyHyphen = threatKey.replace(/_/g, "-");
    const mappedPattern = THREAT_PATTERN_DIRECT_MAP[threatKey];
    return d.threatPattern === threat.pattern || d.threatPattern === threatKeyHyphen || mappedPattern !== undefined && mappedPattern === d.threatPattern;
  }) ?? null;
}
function generateFixSuggestion(finding, threat, defense) {
  const desc = finding.description.toLowerCase();
  if (desc.includes("floating promise"))
    return "Add `await` before async call or use `.then()` chain";
  if (desc.includes("empty catch"))
    return "Add error logging or re-throw the error";
  if (desc.includes("empty function body"))
    return "Add real implementation logic";
  if (desc.includes("returns literal value"))
    return "Replace with computed result";
  if (desc.includes("returns success claim"))
    return "Add preceding side-effect calls before return";
  if (desc.includes("bare return"))
    return "Return a meaningful value or remove the function";
  if (desc.includes("dead code") || desc.includes("never called"))
    return "Remove unused function or add a call site";
  if (desc.includes("duplicate") || desc.includes("similarity"))
    return "Extract shared logic into a helper function";
  if (desc.includes("trivial body"))
    return "Add real computation to the function body";
  return `Apply ${defense.checkMethod} defense rule`;
}
