// src/warheads/container-testing/tmux-session.ts
init_utils();
import { execSync as execSync7 } from "child_process";

class TmuxSession {
  sessionName = null;
  create(containerName, workspace) {
    try {
      execSync7("which tmux", { timeout: 5000 });
      const sessionName = `trident-test-${containerName.substring(0, 8)}`;
      const wd = workspace || "/root/OPENCODE_WORKSPACE";
      execSync7(`tmux new-session -d -s ${sessionName} -c ${wd} "docker exec -it ${containerName} opencode 2>&1; bash"`, { timeout: 1e4 });
      this.sessionName = sessionName;
      tridentLog("INFO", "tmux-session", `Session created: ${sessionName}`);
      return sessionName;
    } catch (e) {
      tridentLog("WARN", "tmux-session", `Failed to create tmux session: ${e instanceof Error ? e.message : String(e)}`);
      return null;
    }
  }
  sendKeys(command) {
    if (!this.sessionName)
      return false;
    try {
      const sendOut = execSync7(`tmux send-keys -t ${this.sessionName} "${command}" Enter`, { timeout: 5000 });
      sendOut.toString();
      return true;
    } catch (e) {
      tridentLog("ERROR", "tmux-session", `Failed to send keys: ${e instanceof Error ? e.message : String(e)}`);
      return false;
    }
  }
  capturePane() {
    if (!this.sessionName)
      return "";
    try {
      const raw = execSync7(`tmux capture-pane -t ${this.sessionName} -p`, { timeout: 5000 });
      return raw.toString();
    } catch (e) {
      console.error("[TmuxSession] error:", e);
      return "";
    }
  }
  kill() {
    if (!this.sessionName)
      return true;
    try {
      if (this.sessionName) {}
      const killOut = execSync7(`tmux kill-session -t ${this.sessionName} 2>/dev/null`, { timeout: 5000 });
      killOut.toString();
      tridentLog("INFO", "tmux-session", `Session killed: ${this.sessionName}`);
      this.sessionName = null;
      return true;
    } catch (e) {
      console.error("[TmuxSession] error:", e);
      return false;
    }
  }
}

// src/warheads/container-testing/deploy-verifier.ts
init_utils();
import { execSync as execSync8 } from "child_process";
import * as fs64 from "fs";
import * as crypto7 from "crypto";

class DeployVerifier {
  verifySha256(filePath, expectedHash, containerId) {
    try {
      const content = fs64.readFileSync(filePath);
      const actual = crypto7.createHash("sha256").update(content).digest("hex");
      let expected;
      if (expectedHash) {
        expected = expectedHash;
      } else if (containerId) {
        try {
          const containerHashRaw = execSync8(`docker exec ${containerId} sha256sum "${filePath}"`, { timeout: 1e4 });
          const containerHash = containerHashRaw.toString().trim().split(/\s+/)[0];
          expected = containerHash;
        } catch (e) {
          tridentLog("ERROR", "deploy-verifier", `Container SHA256 computation failed: ${e instanceof Error ? e.message : String(e)}`);
          return { match: false, expected: "", actual };
        }
      } else {
        tridentLog("WARN", "deploy-verifier", "No expectedHash or containerId provided \u2014 cannot verify SHA256");
        return { match: false, expected: "", actual };
      }
      return { match: actual === expected, expected, actual };
    } catch (e) {
      tridentLog("ERROR", "deploy-verifier", `SHA256 verification failed: ${e instanceof Error ? e.message : String(e)}`);
      return { match: false, expected: "", actual: "" };
    }
  }
  isProcessRunning(containerId, processName) {
    try {
      const raw = execSync8(`docker exec ${containerId} pgrep -f "${processName}"`, { timeout: 5000 });
      const result2 = raw.toString().trim();
      return result2.length > 0;
    } catch (e) {
      console.error("[DeployVerifier] error:", e);
      return false;
    }
  }
  fileExistsInContainer(containerId, filePath) {
    try {
      const testOut = execSync8(`docker exec ${containerId} test -f "${filePath}"`, { timeout: 5000 });
      testOut.toString();
      return true;
    } catch (e) {
      console.error("[DeployVerifier] error:", e);
      return false;
    }
  }
}

