      execSync9(POSEIDON_CONFIG.containerTesting.buildCommand, { cwd: this.targetPath, encoding: "utf-8", timeout: 120000, stdio: "pipe" });
      const distPath = path72.join(this.targetPath, "dist");
      if (!fs65.existsSync(distPath)) {
        return { success: false, error: "Build completed but dist directory not found", evidence };
      }
