// src/warheads/p1-p10-scanner/scanner.ts
init_utils();
import * as fs75 from "fs";
import * as path84 from "path";

class P1P10Scanner {
  scanDirectory(targetPath) {
    const results = [];
    const tsFiles = this.findTsFiles(targetPath);
    for (const file2 of tsFiles) {
      try {
        const content = fs75.readFileSync(file2, "utf-8");
        const lines = content.split(`
`);
        results.push(...this.checkP1_typeofGuard(file2, lines, content));
        results.push(...this.checkP2_castGuard(file2, lines));
        results.push(...this.checkP3_errorComplete(file2, lines));
        results.push(...this.checkP4_cleanup(file2, lines));
        results.push(...this.checkP5_snapshot(file2, lines));
        results.push(...this.checkP6_depCheck(file2, lines));
        results.push(...this.checkP7_pathResolution(file2, lines));
        results.push(...this.checkP8_configValidate(file2, lines));
        results.push(...this.checkP9_asyncDiscipline(file2, lines));
        results.push(...this.checkP10_unionReturn(file2, lines));
      } catch (e) {
        tridentLog("DEBUG", "p1-p10-scanner", `Skipping unreadable file ${file2}: ${e instanceof Error ? e.message : String(e)}`);
        continue;
        return results;
      }
    }
    return results;
  }
  checkP1_typeofGuard(file2, lines, content) {
    const results = [];
    const hasRequire = content.includes("require(") || content.includes("import(");
    const hasTypeof = content.includes("typeof") || content.includes("?.");
    if (hasRequire && !hasTypeof) {
      results.push({
        principle: "P1",
        name: "Defensive Import",
        passed: false,
        file: file2,
        line: 1,
        detail: "Dynamic import without typeof guard \u2014 may fail at runtime"
      });
    }
    return results;
  }
  checkP2_castGuard(file2, lines) {
    const results = [];
    const SAFE_CAST_PATTERNS = [
      /\bas\s+const\b/,
      /\bas\s+unknown\b/,
      /\bas\s+Error\b/
    ];
    for (let i = 0;i < lines.length; i++) {
      const line = lines[i];
      if (line.trim().startsWith("import ") || line.trim().startsWith("export "))
        continue;
      const asCastMatch = line.match(/\bas\s+(\w+)/);
      if (asCastMatch && !line.includes("/*") && !line.includes("//")) {
        if (SAFE_CAST_PATTERNS.some((re) => re.test(line)))
          continue;
        const prevLine = i > 0 ? lines[i - 1] : "";
        const hasGuard = line.includes("if (") || line.includes("&&") || line.includes("||") || prevLine.includes("if (") || prevLine.includes("&&") || prevLine.includes("||") || line.includes("!") || prevLine.includes("!");
        if (!hasGuard) {
          results.push({
            principle: "P2",
            name: "Cast Guard",
            passed: false,
            file: file2,
            line: i + 1,
            detail: `Unprotected 'as ${asCastMatch[1]}' cast \u2014 add guard before cast`
          });
        }
      }
    }
    return results;
  }
  checkP3_errorComplete(file2, lines) {
    const results = [];
    const emptyCatchRe = /catch\s*\([^)]*\)\s*\{\s*\}/;
    for (let i = 0;i < lines.length; i++) {
      if (emptyCatchRe.test(lines[i])) {
        results.push({
          principle: "P3",
          name: "Error Completeness",
          passed: false,
          file: file2,
          line: i + 1,
          detail: "Empty catch block \u2014 must log+recover or log+propagate"
        });
      }
      if (lines[i].includes("catch (") && lines[i].includes("{") && !lines[i].includes("}")) {
        const remaining = lines.slice(i).join(" ");
        if (/catch\s*\([^)]*\)\s*\{[\s]*\}/.test(remaining)) {
          results.push({
            principle: "P3",
            name: "Error Completeness",
            passed: false,
            file: file2,
            line: i + 1,
            detail: "Empty catch block \u2014 must log+recover or log+propagate"
          });
        }
      }
    }
    return results;
  }
  checkP4_cleanup(file2, lines) {
    const results = [];
    for (let i = 0;i < lines.length; i++) {
      if (lines[i].includes("setInterval(") || lines[i].includes("setTimeout(")) {
        const surrounding = lines.slice(Math.max(0, i - 5), i + 20).join(`
`);
        const hasCleanup = surrounding.includes("clearInterval") || surrounding.includes("clearTimeout");
        if (!hasCleanup) {
          results.push({
            principle: "P4",
            name: "Resource Lifecycle",
            passed: false,
            file: file2,
            line: i + 1,
            detail: "setInterval/setTimeout without clearInterval/clearTimeout \u2014 resource leak"
          });
        }
      }
      if (lines[i].includes(".open(") && lines[i].includes("fs") || lines[i].includes("createReadStream") || lines[i].includes("createWriteStream")) {
        const surrounding = lines.slice(Math.max(0, i - 2), i + 15).join(`
`);
        const hasClose = surrounding.includes(".close(") || surrounding.includes(".end(");
        if (!hasClose) {
          results.push({
            principle: "P4",
            name: "Resource Lifecycle",
            passed: false,
            file: file2,
            line: i + 1,
            detail: "File handle opened without .close() in finally block"
          });
        }
      }
    }
    return results;
  }
  checkP5_snapshot(file2, lines) {
    const results = [];
    for (let i = 0;i < lines.length; i++) {
      if (lines[i].includes(".push(") || lines[i].includes(".splice(") || lines[i].includes(".set(")) {
        const prevLine = i > 0 ? lines[i - 1] : "";
        const isNewVar = prevLine.includes("const ") || prevLine.includes("let ") || prevLine.includes("var ");
        if (!isNewVar) {
          results.push({
            principle: "P5",
            name: "Atomic State",
            passed: true,
            file: file2,
            line: i + 1,
            detail: "Direct mutation \u2014 consider snapshot pattern"
          });
        }
      }
    }
    return results;
  }
  checkP6_depCheck(file2, lines) {
    const results = [];
    for (let i = 0;i < lines.length; i++) {
      if (lines[i].includes("require(") && lines[i].includes("try")) {
        continue;
      }
      if (lines[i].includes("require(") && !lines[i].includes("import")) {
        results.push({
          principle: "P6",
          name: "Dependency Check",
          passed: false,
          file: file2,
          line: i + 1,
          detail: "require() without try/catch \u2014 may throw if module missing"
        });
      }
    }
    return results;
  }
  checkP7_pathResolution(file2, lines) {
    const results = [];
    const hardcodedPathRe = /['"`](\/home\/|\/root\/|\/var\/|\/etc\/|\/tmp\/)/;
    for (let i = 0;i < lines.length; i++) {
      if (hardcodedPathRe.test(lines[i]) && !lines[i].includes("process.env")) {
        results.push({
          principle: "P7",
          name: "Path Resolution",
          passed: false,
          file: file2,
          line: i + 1,
          detail: "Hardcoded absolute path \u2014 use path.join(os.homedir(), ...)"
        });
      }
    }
    return results;
  }
  checkP8_configValidate(file2, lines) {
    const results = [];
    for (let i = 0;i < lines.length; i++) {
      if (lines[i].includes("process.env.") && !lines[i].includes("||") && !lines[i].includes("??")) {
        results.push({
          principle: "P8",
          name: "Config Validation",
          passed: false,
          file: file2,
          line: i + 1,
          detail: "process.env access without default value \u2014 may be undefined"
        });
      }
    }
    return results;
  }
  checkP9_asyncDiscipline(file2, lines) {
    const results = [];
    for (let i = 0;i < lines.length; i++) {
      if (lines[i].includes("async ") && lines[i].includes("=>") || lines[i].includes("async function")) {
        const bodyStart = i;
        let bodyLines = "";
        let j = i + 1;
        let braceCount = 0;
        let started = false;
        while (j < Math.min(i + 50, lines.length)) {
          bodyLines += lines[j] + `
`;
          if (lines[j].includes("{")) {
            started = true;
            braceCount += (lines[j].match(/{/g) || []).length;
          }
          if (lines[j].includes("}")) {
            braceCount -= (lines[j].match(/}/g) || []).length;
          }
          if (started && braceCount <= 0)
            break;
          j++;
        }
        const hasTryCatch = bodyLines.includes("try") && bodyLines.includes("catch");
        const hasDotCatch = bodyLines.includes(".catch(");
        if (!hasTryCatch && !hasDotCatch && bodyLines.includes("await")) {
          results.push({
            principle: "P9",
            name: "Async Discipline",
            passed: false,
            file: file2,
            line: i + 1,
            detail: "async function with await but no try/catch or .catch()"
          });
        }
      }
    }
    return results;
  }
  checkP10_unionReturn(file2, lines) {
    const results = [];
    for (let i = 0;i < lines.length; i++) {
      if (lines[i].includes("function ") && lines[i].includes(":")) {
        const returnTypeMatch = lines[i].match(/:\s*(\w+(?:<\w+>)?)/);
        if (returnTypeMatch) {
          const type3 = returnTypeMatch[1];
          if (type3 === "any" || type3 === "unknown") {
            results.push({
              principle: "P10",
              name: "Output Contract",
              passed: false,
              file: file2,
              line: i + 1,
              detail: `Return type '${type3}' is too loose \u2014 use discriminated union`
            });
          }
        }
      }
      if (lines[i].includes("return;") || lines[i].includes("return undefined")) {
        const funcLine = this.findEnclosingFunction(lines, i);
        if (funcLine >= 0) {
          if (/void\s/.test(lines[funcLine]))
            continue;
          results.push({
            principle: "P10",
            name: "Output Contract",
            passed: false,
            file: file2,
            line: funcLine + 1,
            detail: "Function has bare return/undefined return \u2014 missing return value"
          });
        }
      }
    }
    return results;
  }
  findTsFiles(dir) {
    const files = [];
    const walkDir = (d, depth) => {
      if (depth > 15)
        return;
      try {
        const entries = fs75.readdirSync(d, { withFileTypes: true });
        for (const entry of entries) {
          if (entry.name === "node_modules" || entry.name === "dist" || entry.name === ".git" || entry.name === "src_old")
            continue;
          if (entry.isSymbolicLink && entry.isSymbolicLink())
            continue;
          const fullPath = path84.join(d, entry.name);
          if (entry.isDirectory())
            walkDir(fullPath, depth + 1);
          else if (entry.name.endsWith(".ts") && !entry.name.endsWith(".d.ts"))
            files.push(fullPath);
        }
      } catch (e) {
        console.error("[Scanner] error:", e);
      }
    };
    walkDir(dir, 0);
    return files;
  }
  findEnclosingFunction(lines, lineIndex) {
    for (let i = lineIndex;i >= 0; i--) {
      if (lines[i].includes("function ") || lines[i].includes("=>") && lines[i].includes("(")) {
        return i;
      }
    }
    return -1;
  }
}

// src/warheads/p1-p10-scanner/index.ts
init_utils();
class P1P10Verification {
  scanner;
  lastResults = [];
  constructor() {
    this.scanner = new P1P10Scanner;
    tridentLog("INFO", "p1-p10", "P1-P10 Scanner initialized");
  }
  scan(targetPath) {
    try {
      this.lastResults = this.scanner.scanDirectory(targetPath);
    } catch (e) {
      tridentLog("ERROR", "p1-p10", `Scanner crashed, continuing with empty results: ${e instanceof Error ? e.message : String(e)}`);
      this.lastResults = [];
    }
    const totalChecks = this.lastResults.length;
    const passed = this.lastResults.filter((r) => r.passed).length;
    const score2 = totalChecks > 0 ? Math.round(passed / totalChecks * 100) : 100;
    tridentLog("INFO", "p1-p10", `Scan complete: ${passed}/${totalChecks} passed (${score2}%)`);
    return { results: this.lastResults, score: score2 };
  }
  getLastResults() {
    return [...this.lastResults];
  }
}

